/* parse_nums.cpp - modern C++17 rewrite of legacy argument parser.
 *
 * The program keeps the exact observable behaviour of the original C
 * implementation: the same output text, formatting and exit codes.
 * It uses std::string, std::vector and RAII for safety, but still
 * relies on the C library for the numeric conversions because the
 * legacy behaviour of atoi/atof is required (e.g. atoi("12abc") == 12,
 * atoi("abc") == 0, never throws).
 */

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

/* Helper that mimics the behaviour of atoi.
 * It stops parsing at the first non‑digit, returns 0 if no digits
 * are found, and never throws. */
static int legacy_atoi(const char* s)
{
    if (!s) return 0;
    char* endptr = nullptr;
    long val = std::strtol(s, &endptr, 10);
    /* strtol will return 0 if the first character is not a valid
     * digit.  The original atoi also returns 0 in that case. */
    return static_cast<int>(val);
}

/* Helper that mimics the behaviour of atof.
 * It uses strtod which behaves like the legacy atof. */
static double legacy_atof(const char* s)
{
    if (!s) return 0.0;
    char* endptr = nullptr;
    double val = std::strtod(s, &endptr);
    return val;
}

int main(int argc, char** argv)
{
    /* Convert the C array of C strings into a vector of std::string
     * for easier manipulation and to guarantee RAII. */
    std::vector<std::string> args(argv + 1, argv + argc);

    if (args.empty()) {
        std::printf("nothing to parse\n");
        return 0;
    }

    long total = 0;
    for (const auto& arg : args) {
        int v   = legacy_atoi(arg.c_str());
        double d = legacy_atof(arg.c_str());

        /* The original program used printf with a fixed format.
         * We keep the same format to preserve the exact output. */
        std::printf("%-8s -> int %d, double %.3f, div7 %d, mod7 %d\n",
                    arg.c_str(), v, d, v / 7, v % 7);

        total += v;
    }

    std::printf("total %ld\n", total);
    /* Exit code 1 if the total is negative, otherwise 0. */
    return total < 0 ? 1 : 0;
}
